import numpy as np
import time

def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds

    # Try multiple N values; start from a good guess and refine.
    # C(f) = 2N * max(conv(h,h)) / (sum h)^2
    # The optimal shape near a triangle gives C ~ 1.5... aim lower.

    def score(h):
        h = np.asarray(h, dtype=float)
        s = h.sum()
        if s <= 0:
            return np.inf
        c = np.convolve(h, h)
        return 2.0 * len(h) * c.max() / (s * s)

    best_h = None
    best_c = np.inf
    if start is not None:
        try:
            hs = np.asarray(start, dtype=float)
            if hs.size > 0 and hs.sum() > 0:
                best_h = hs.copy()
                best_c = score(best_h)
        except Exception:
            pass

    # Candidate N values to try
    Ns = [50, 100, 200, 400, 800, 1500, 3000, 6000, 12000, 24000, 30000]

    # Initial shape: triangle-like (smooth bump) scaled
    def make_init(N, kind=0):
        x = np.linspace(-1, 1, N)
        if kind == 0:
            h = np.clip(1 - np.abs(x), 0, None) + 1e-3
        elif kind == 1:
            h = np.cos(x * np.pi / 2) ** 2 + 1e-3
        else:
            h = np.ones(N)
        return h

    # Coordinate-descent / multiplicative refinement on heights
    def refine(h, iters, deadline):
        h = h.astype(float).copy()
        N = len(h)
        cur = score(h)
        # Work on a downsampled parameterization for large N
        for it in range(iters):
            if time.process_time() > deadline:
                break
            # sample a subset of indices to perturb, plus neighbors
            idxs = np.random.randint(0, N, size=max(1, min(N, 30)))
            improved = False
            for i in idxs:
                old = h[i]
                # try multiplicative factors
                for f in (0.5, 0.8, 0.95, 1.05, 1.25, 2.0):
                    h[i] = old * f
                    c = score(h)
                    if c < cur - 1e-12:
                        cur = c
                        old = h[i]
                        improved = True
                    else:
                        h[i] = old
                # additive
                for d in (-0.1*old, 0.1*old):
                    h[i] = max(0.0, old + d)
                    c = score(h)
                    if c < cur - 1e-12:
                        cur = c
                        old = h[i]
                        improved = True
                    else:
                        h[i] = old
            if not improved:
                # small global smoothing step
                pass
        return h, cur

    np.random.seed(12345)

    # First, try each N with a quick init and a few refine iters
    for N in Ns:
        if time.process_time() > t0 + budget * 0.5:
            break
        for kind in (0, 1):
            h = make_init(N, kind)
            h = h / h.sum()
            c = score(h)
            if c < best_c:
                best_c = c
                best_h = h.copy()

    # Now refine best across scales with remaining budget
    deadline = t0 + budget * 0.92
    if best_h is not None:
        # refine current best
        iters = 0
        while time.process_time() < deadline:
            iters += 1
            h2, c2 = refine(best_h, 5, deadline)
            if c2 < best_c - 1e-12:
                best_h, best_c = h2, c2
            else:
                # try local smoothing on best
                h3 = best_h.copy()
                h3 = 0.5 * h3 + 0.25 * (np.roll(h3, 1) + np.roll(h3, -1))
                c3 = score(h3)
                if c3 < best_c - 1e-12:
                    best_h, best_c = h3, c3
                else:
                    break
            if time.process_time() > deadline:
                break

    if best_h is None:
        best_h = np.ones(50)

    best_h = np.asarray(best_h, dtype=float)
    best_h = np.maximum(best_h, 0.0)
    if best_h.sum() <= 0:
        best_h = np.ones(50)

    return best_h

