def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    N = len(h)
    return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    margin = 1.0
    deadline = budget_seconds - margin

    N = 300
    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        # If start has a different length, resample/keep as is; but we want N=300.
        if len(h) != N:
            # interpolate to N points, non-negative
            x_old = np.linspace(0, 1, len(h))
            x_new = np.linspace(0, 1, N)
            h = np.interp(x_new, x_old, h)
            h = np.maximum(h, 0.0)
    else:
        h = np.ones(N)

    factors = np.array([0.5, 0.7, 0.85, 1.0, 1.18, 1.4, 2.0])

    best_C = _C(h)
    best_h = h.copy()

    max_sweeps = 30
    for sweep in range(max_sweeps):
        improved = False
        for i in range(N):
            if time.process_time() - t0 > deadline:
                return best_h
            base_val = h[i]
            local_best = best_C
            local_factor = 1.0
            for f in factors:
                if f == 1.0:
                    continue
                h[i] = base_val * f
                c = _C(h)
                if c < local_best - 1e-15:
                    local_best = c
                    local_factor = f
            h[i] = base_val * local_factor
            if local_factor != 1.0:
                best_C = local_best
                improved = True
        if best_C < _C(best_h):
            best_h = h.copy()
        if not improved:
            break

    if _C(h) < _C(best_h):
        best_h = h.copy()
    return best_h

import numpy as np
import time
from scipy.optimize import differential_evolution, minimize


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 1000
    K = 12

    # Coarse-grain start into K segments to seed
    seed_heights = None
    if start is not None:
        h0 = np.asarray(start, dtype=float).ravel()
        if h0.size > 0:
            # resample to K by averaging blocks
            idx = np.linspace(0, h0.size, K + 1).astype(int)
            seed_heights = np.array([
                h0[idx[i]:max(idx[i] + 1, idx[i + 1])].mean()
                for i in range(K)
            ])
            if seed_heights.sum() <= 0:
                seed_heights = None
            else:
                seed_heights = seed_heights / seed_heights.max()

    def build_h(x):
        # x: K heights (log) and K-1 boundaries in (0,1)
        heights = np.exp(x[:K])
        b = np.sort(x[K:])
        # map boundaries to step indices in [1, N-1]
        b = np.clip(b, 1e-6, 1 - 1e-6)
        edges = np.concatenate([[0], np.round(b * N).astype(int), [N]])
        edges = np.maximum.accumulate(edges)
        # ensure strictly increasing where possible
        for i in range(1, len(edges)):
            if edges[i] <= edges[i - 1]:
                edges[i] = min(edges[i - 1] + 1, N)
        edges[-1] = N
        h = np.empty(N)
        for i in range(K):
            a, c = edges[i], edges[i + 1]
            if c <= a:
                c = min(a + 1, N)
            h[a:c] = heights[i]
        return h

    def objective(x):
        h = build_h(x)
        S = h.sum()
        if S <= 0:
            return 1e10
        c = np.convolve(h, h)
        return 2.0 * N * c.max() / (S * S)

    # Bounds: log heights in [log(1e-6), log(10)], boundaries in (0,1)
    bounds = [(np.log(1e-6), np.log(10.0))] * K + [(0.0, 1.0)] * (K - 1)

    # Build initial population
    np.random.seed(12345)
    popsize = 20
    init = []
    if seed_heights is not None:
        x0 = np.concatenate([
            np.log(np.maximum(seed_heights, 1e-6)),
            np.linspace(0.05, 0.95, K - 1)
        ])
        init.append(x0)
    # random individuals
    n_rand = popsize * (2 * K) - len(init)
    for _ in range(n_rand):
        xh = np.random.uniform(np.log(1e-3), np.log(3.0), K)
        xb = np.sort(np.random.uniform(0.02, 0.98, K - 1))
        init.append(np.concatenate([xh, xb]))
    init = np.array(init)

    best_x = None
    best_val = np.inf

    try:
        # Run DE with a time-limited callback
        def cb(xk, convergence=None):
            return time.process_time() > deadline

        res = differential_evolution(
            objective, bounds, init=init, maxiter=200, tol=1e-8,
            mutation=(0.5, 1.0), recombination=0.7, polish=False,
            callback=cb, seed=1, updating='immediate'
        )
        if res.fun < best_val:
            best_val = res.fun
            best_x = res.x.copy()
    except Exception:
        pass

    # Fallback: evaluate seed
    if best_x is None and seed_heights is not None:
        best_x = np.concatenate([
            np.log(np.maximum(seed_heights, 1e-6)),
            np.linspace(0.05, 0.95, K - 1)
        ])
        best_val = objective(best_x)

    # Polish with Powell if time remains
    if best_x is not None and time.process_time() < deadline:
        try:
            res2 = minimize(
                objective, best_x, method='Powell',
                options={'maxiter': 500, 'xtol': 1e-8, 'ftol': 1e-10}
            )
            if res2.fun < best_val:
                best_val = res2.fun
                best_x = res2.x.copy()
        except Exception:
            pass

    # Final: also compare against resampled start at N=1000
    cand = None
    if best_x is not None:
        cand = build_h(best_x)
    if start is not None:
        h0 = np.asarray(start, dtype=float).ravel()
        if h0.size != N:
            x_old = np.linspace(0, 1, h0.size)
            x_new = np.linspace(0, 1, N)
            h_start = np.interp(x_new, x_old, h0)
        else:
            h_start = h0.copy()
        h_start = np.maximum(h_start, 0.0)
        if h_start.sum() > 0:
            C_start = 2.0 * N * np.convolve(h_start, h_start).max() / (h_start.sum() ** 2)
            if cand is None:
                cand = h_start
                best_val = C_start
            else:
                C_cand = 2.0 * N * np.convolve(cand, cand).max() / (cand.sum() ** 2)
                if C_start < C_cand:
                    cand = h_start
                    best_val = C_start

    if cand is None:
        cand = np.ones(N)

    # Ensure non-negative, not all zero
    cand = np.maximum(cand, 0.0)
    if cand.sum() <= 0:
        cand = np.ones(N)

    print(f"final C ~ {best_val:.6f}, N={N}, K={K}")
    return cand

import numpy as np
import time
from scipy.optimize import minimize, differential_evolution


def exact_C(h):
    N = h.size
    S = h.sum()
    if S <= 0:
        return np.inf
    return 2.0 * N * np.convolve(h, h).max() / (S * S)


def resample(h, N):
    if h.size == N:
        return np.maximum(h.astype(float), 1e-12)
    xo = np.linspace(0, 1, h.size)
    xn = np.linspace(0, 1, N)
    return np.maximum(np.interp(xn, xo, h), 1e-12)


def slsqp_solve(hc0, maxiter, ftol):
    Nc = hc0.size
    hc0 = np.maximum(hc0, 1e-9)
    s = hc0.sum()
    if s <= 0:
        hc0 = np.ones(Nc)
        s = Nc
    hc0 = hc0 / s

    def obj(x):
        return x[Nc]

    def con_sum(x):
        return x[:Nc].sum() - 1.0

    def con_conv(x):
        h = x[:Nc]
        t = x[Nc]
        return t - np.convolve(h, h)

    x0 = np.concatenate([hc0, [exact_C(hc0) * 1.02]])
    bounds = [(0.0, None)] * Nc + [(0.0, None)]
    constraints = [
        {'type': 'eq', 'fun': con_sum},
        {'type': 'ineq', 'fun': con_conv},
    ]
    try:
        res = minimize(obj, x0, method='SLSQP', bounds=bounds,
                       constraints=constraints,
                       options={'maxiter': maxiter, 'ftol': ftol})
        if res.x is not None and np.all(np.isfinite(res.x)):
            hc = np.maximum(res.x[:Nc], 0.0)
            if hc.sum() > 0:
                return hc / hc.sum()
    except Exception:
        pass
    return hc0


def polish(z, N, deadline, best_h, best_C, lr0=0.0008, seed_noise=1e-3):
    rng = np.random.default_rng(int(time.process_time() * 1e6) & 0xffff)
    beta1, beta2 = 0.9, 0.999
    eps = 1e-8
    m = np.zeros(N)
    v = np.zeros(N)
    step = 0
    while True:
        if time.process_time() > deadline:
            break
        lr = lr0 * 0.5 ** (step // 1500)
        h = np.exp(z)
        S = h.sum()
        c = np.convolve(h, h)
        k = int(np.argmax(c))
        ck = c[k]
        g_h = np.zeros(N)
        j_lo = max(0, k - (N - 1))
        j_hi = min(N - 1, k)
        if j_lo <= j_hi:
            js = np.arange(j_lo, j_hi + 1)
            idx = k - js
            g_h[js] = h[idx]
        g_h = 4.0 * N * (g_h * S - ck) / (S * S * S)
        g_z = g_h * h
        m = beta1 * m + (1 - beta1) * g_z
        v = beta2 * v + (1 - beta2) * (g_z * g_z)
        m_hat = m / (1 - beta1 ** (step + 1))
        v_hat = v / (1 - beta2 ** (step + 1))
        z = z - lr * m_hat / (np.sqrt(v_hat) + eps)
        step += 1
        if step % 300 == 0:
            z = z + seed_noise * rng.standard_normal(N)
        if step % 15 == 0 or step == 1:
            h = np.exp(z)
            C = exact_C(h)
            if C < best_C:
                best_C = C
                best_h = h.copy()
    return z, best_h, best_C


def param_to_h(params, N, nb):
    # params: for each bump: weight, center, width ; plus optional shape flag
    x = np.linspace(-0.25, 0.25, N)
    h = np.zeros(N)
    for i in range(nb):
        w = params[3 * i]
        c = params[3 * i + 1]
        s = params[3 * i + 2]
        if s < 1e-6:
            s = 1e-6
        h += w * np.exp(-0.5 * ((x - c) / s) ** 2)
    return np.maximum(h, 0.0)


def param_search(N, nb, deadline, seed=0):
    # bounds: weight [0,2], center [-0.25,0.25], width [0.005,0.25]
    bounds = []
    for _ in range(nb):
        bounds += [(0.0, 2.0), (-0.25, 0.25), (0.005, 0.25)]

    def obj(p):
        h = param_to_h(p, N, nb)
        if h.sum() <= 0:
            return 1e6
        return exact_C(h)

    best = [None, np.inf]
    try:
        res = differential_evolution(
            obj, bounds, maxiter=60, popsize=12, tol=1e-6,
            mutation=(0.5, 1.0), recombination=0.8, seed=seed,
            polish=True, init='latinhypercube')
        if res.fun < best[1]:
            best = [res.x, res.fun]
    except Exception:
        pass
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 2400

    if start is not None:
        h0 = resample(np.asarray(start, dtype=float).ravel(), N)
    else:
        x = np.linspace(-1, 1, N)
        h0 = np.exp(-4.0 * x * x)

    best_h = h0.copy()
    best_C = exact_C(best_h)

    x_old = np.linspace(0, 1, N)

    # --- Parametric multi-bump search on coarse grid ---
    Np = 600
    for nb in (2, 3):
        if time.process_time() > deadline - 2.0:
            break
        # allocate a slice of time for this search
        slice_deadline = min(deadline - 1.0, time.process_time() + 3.0)
        # run a bounded DE
        bounds = []
        for _ in range(nb):
            bounds += [(0.0, 2.0), (-0.25, 0.25), (0.005, 0.25)]

        def obj(p):
            h = param_to_h(p, Np, nb)
            if h.sum() <= 0:
                return 1e6
            return exact_C(h)

        try:
            res = differential_evolution(
                obj, bounds, maxiter=40, popsize=10, tol=1e-5,
                mutation=(0.5, 1.0), recombination=0.8, seed=nb,
                polish=True, init='latinhypercube')
            if res.x is not None and np.isfinite(res.fun):
                hp = param_to_h(res.x, Np, nb)
                hu = resample(hp, N)
                Cu = exact_C(hu)
                if Cu < best_C:
                    best_h = hu.copy()
                    best_C = Cu
        except Exception:
            pass

    # --- Cascade of constrained solves (warm-started) ---
    hc = resample(best_h, 120)
    for Nc, mi, ft in [(120, 200, 1e-9), (240, 200, 1e-10), (480, 250, 1e-11)]:
        if time.process_time() > deadline:
            break
        xc = np.linspace(0, 1, Nc)
        hc = np.interp(xc, np.linspace(0, 1, hc.size), hc)
        hc = slsqp_solve(hc, maxiter=mi, ftol=ft)
        hu = resample(np.interp(x_old, xc, hc), N)
        Cu = exact_C(hu)
        if Cu < best_C:
            best_h = hu.copy()
            best_C = Cu

    # --- Adam subgradient polish on log-heights ---
    if time.process_time() < deadline:
        z = np.log(np.maximum(best_h, 1e-10))
        z, best_h, best_C = polish(z, N, deadline, best_h, best_C)

    # --- Random restarts from perturbed best ---
    while time.process_time() < deadline:
        z2 = np.log(np.maximum(best_h, 1e-10)) + 5e-4 * np.random.randn(N)
        z2, bh2, bc2 = polish(z2, N, deadline, best_h, best_C)
        if bc2 < best_C:
            best_h, best_C = bh2, bc2
        if time.process_time() > deadline - 0.2:
            break

    return best_h

