import numpy as np
import time


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 2000
    x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)

    best_C = np.inf
    best_h = None

    rs = np.arange(1.0, 8.0 + 1e-9, 0.05)
    # Precompute cumulative sums trick: for each s, sum = s_idx + r*(N-s_idx)
    # max convolution still needs full convolve, so we loop.
    # To save time, we do a coarse pass then refine around the best.

    def evaluate(r, s_idx):
        h = np.where(np.arange(N) < s_idx, 1.0, r)
        return _C(h), h

    # Coarse: s in steps of 20
    for r in rs:
        for s_idx in range(0, N + 1, 20):
            if time.process_time() - t0 > budget_seconds * 0.6:
                break
            c, h = evaluate(r, s_idx)
            if c < best_C:
                best_C = c
                best_h = h
        if time.process_time() - t0 > budget_seconds * 0.6:
            break

    # Refine around best
    if best_h is not None:
        # find best r and s roughly from best_h
        # re-search finer near best
        r_best = None
        s_best = None
        for r in rs:
            for s_idx in range(0, N + 1, 5):
                if time.process_time() - t0 > budget_seconds * 0.85:
                    break
                c, h = evaluate(r, s_idx)
                if c < best_C:
                    best_C = c
                    best_h = h
                    r_best = r
                    s_best = s_idx
            if time.process_time() - t0 > budget_seconds * 0.85:
                break

    if best_h is None:
        # fallback
        best_h = np.ones(50)

    if start is not None:
        st = np.asarray(start, dtype=float)
        if _C(st) < best_C:
            return st

    return best_h

import numpy as np
import time


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _resample(h, n_new):
    """Resample a step function onto n_new steps preserving the profile."""
    n = len(h)
    if n == n_new:
        return h.copy()
    # Treat h as samples of a piecewise-constant function on [0,1); integrate to CDF then invert.
    edges_old = np.linspace(0.0, 1.0, n + 1)
    dens = h / (1.0 / n)  # density per unit length (sum of h*n = integral)
    cdf = np.concatenate([[0.0], np.cumsum(h)]) / h.sum()
    # For each new cell center, evaluate the old step function
    centers = (np.arange(n_new) + 0.5) / n_new
    x_old = (np.arange(n) + 0.5) / n
    vals = np.interp(centers, x_old, h, left=h[0], right=h[-1])
    if vals.sum() <= 0:
        return np.ones(n_new)
    return vals


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds * 0.90

    def time_left():
        return deadline - (time.process_time() - t0)

    # Start candidate
    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)

    base_c = C_of(base)

    # The key insight: finer grids give more freedom. Try many N and pick the best,
    # then do targeted local search where the convolution maximum is achieved.
    rng = np.random.default_rng(987654321)

    def local_search(h, time_budget, rng):
        """Coordinate/local search on h, restricted to a neighborhood of the peak."""
        cur = h.copy()
        cur_c = C_of(cur)
        n = len(cur)
        end = time.process_time() + time_budget

        # Precompute step size schedule
        steps = [0.3, 0.15, 0.08, 0.04, 0.02, 0.01, 0.005, 0.002, 0.001, 0.0005]
        si = 0
        stalls = 0
        while time.process_time() < end and si < len(steps):
            eps = steps[si]
            improved = False
            # Sweep blocks
            for _ in range(60):
                if time.process_time() >= end:
                    break
                bl = int(rng.integers(1, max(2, n // 3 + 1)))
                i0 = int(rng.integers(0, n - bl + 1))
                sign = 1.0 if rng.random() < 0.5 else -1.0
                h2 = cur.copy()
                h2[i0:i0 + bl] *= (1.0 + sign * eps)
                if np.any(h2 < 0):
                    continue
                s = h2.sum()
                if s <= 0:
                    continue
                c2 = C_of(h2)
                if c2 < cur_c - 1e-14:
                    cur, cur_c = h2, c2
                    improved = True
            if not improved:
                # try additive perturbation of a block
                for _ in range(40):
                    if time.process_time() >= end:
                        break
                    bl = int(rng.integers(1, max(2, n // 4 + 1)))
                    i0 = int(rng.integers(0, n - bl + 1))
                    h2 = cur.copy()
                    delta = eps * cur.mean() * rng.standard_normal(bl)
                    h2[i0:i0 + bl] = np.maximum(h2[i0:i0 + bl] + delta, 0.0)
                    s = h2.sum()
                    if s <= 0:
                        continue
                    c2 = C_of(h2)
                    if c2 < cur_c - 1e-14:
                        cur, cur_c = h2, c2
                        improved = True
                if not improved:
                    stalls += 1
                    if stalls >= 2:
                        si += 1
                        stalls = 0
            else:
                stalls = 0
        return cur, cur_c

    # Try candidates at multiple resolutions
    best_h = base.copy()
    best_c = base_c

    # Resample to a set of sizes and locally optimize each, keeping best.
    sizes = [50, 80, 120, 180, 260, 380, 540, 760, 1080, 1500, 2100, 2900]
    # Budget per size proportional to log(size) for fairness
    total_weight = sum(np.log(s) for s in sizes)
    for idx, n in enumerate(sizes):
        if time_left() <= 0.5:
            break
        h0 = _resample(base, n) if n != len(base) else base.copy()
        # allocate time
        w = np.log(n) / total_weight
        tb = min(time_left() * 0.85, w * (budget_seconds * 0.80))
        if tb <= 0.05:
            continue
        h_opt, c_opt = local_search(h0, tb, rng)
        if c_opt < best_c - 1e-12:
            best_h, best_c = h_opt, c_opt

    # Final polish on the best at its own resolution, plus one more refinement attempt.
    if time_left() > 0.5:
        h_opt, c_opt = local_search(best_h, time_left() * 0.9, rng)
        if c_opt < best_c:
            best_h, best_c = h_opt, c_opt

    # Try a finer version of the best (resampling) as a last check.
    if time_left() > 0.5:
        for n in [len(best_h) * 2, len(best_h) * 3]:
            if n > 30000 or time_left() <= 0.3:
                continue
            h2 = _resample(best_h, n)
            c2 = C_of(h2)
            if c2 < best_c:
                best_h, best_c = h2, c2

    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _slsqp_polish(h0, N, maxiter, t0, budget):
    """Run SLSQP on the constraint formulation starting from h0 (length N)."""
    h0 = np.asarray(h0, dtype=float)
    h0 = np.clip(h0, 0.0, None)
    if h0.sum() <= 0:
        return None, np.inf
    h0 = h0 / h0.sum()
    c0 = _C(h0)

    pairs = [[] for _ in range(2 * N - 1)]
    for i in range(N):
        for j in range(N):
            pairs[i + j].append((i, j))

    def obj(v):
        return v[N]

    def obj_grad(v):
        g = np.zeros(N + 1)
        g[N] = 1.0
        return g

    def conv_constraint(v):
        return v[N] - np.convolve(v[:N], v[:N])

    def conv_jac(v):
        h = v[:N]
        J = np.zeros((2 * N - 1, N + 1))
        for k in range(2 * N - 1):
            for (i, j) in pairs[k]:
                if i == j:
                    J[k, i] += -2.0 * h[i]
                else:
                    J[k, i] += -h[j]
                    J[k, j] += -h[i]
            J[k, N] = 1.0
        return J

    cons = [
        {'type': 'eq', 'fun': lambda v: np.sum(v[:N]) - 1.0,
         'jac': lambda v: np.concatenate([np.ones(N), [0.0]])},
        {'type': 'ineq', 'fun': conv_constraint, 'jac': conv_jac},
    ]
    bounds = [(0.0, None)] * N + [(0.0, None)]
    v0 = np.concatenate([h0, [c0]])

    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-12})
        v = res.x
    except Exception:
        return h0, c0

    h = np.clip(v[:N], 0.0, None)
    if h.sum() <= 0:
        return h0, c0
    h = h / h.sum()
    c = _C(h)
    if c < c0:
        return h, c
    return h0, c0


def _seeds(N, rng):
    x = np.linspace(-1.0, 1.0, N)
    seeds = []
    for a in [-4.0, -2.0, -1.0, 0.0, 1.0, 2.0, 4.0]:
        h = np.exp(a * x)
        h /= h.sum()
        seeds.append(h)
    h = 1.0 + np.cos(np.pi * x)
    h = np.clip(h, 0.0, None)
    h /= h.sum()
    seeds.append(h)
    for _ in range(4):
        h = rng.lognormal(0.0, 1.0, N)
        # 3-point moving average
        hp = np.concatenate([[h[0]], h, [h[-1]]])
        h = (hp[:-2] + hp[1:-1] + hp[2:]) / 3.0
        h = np.clip(h, 0.0, None)
        if h.sum() <= 0:
            h = np.ones(N)
        h /= h.sum()
        seeds.append(h)
    return seeds


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.85
    rng = np.random.default_rng(12345)

    best_h = None
    best_c = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            cs = _C(s)
            if np.isfinite(cs):
                best_h = s.copy()
                best_c = cs

    # Multi-start at several N
    for N, maxiter in [(40, 500), (80, 500), (160, 500)]:
        if time.process_time() - t0 > budget:
            break
        for seed in _seeds(N, rng):
            if time.process_time() - t0 > budget:
                break
            h, c = _slsqp_polish(seed, N, maxiter, t0, budget)
            if h is not None and c < best_c:
                best_h = h
                best_c = c

    # Upsample best to N=320 and polish
    if best_h is not None and time.process_time() - t0 < budget:
        N2 = 320
        x_old = np.linspace(0.0, 1.0, len(best_h))
        x_new = np.linspace(0.0, 1.0, N2)
        h_up = np.interp(x_new, x_old, best_h)
        h_up = np.clip(h_up, 0.0, None)
        if h_up.sum() > 0:
            h_up /= h_up.sum()
            h, c = _slsqp_polish(h_up, N2, 1000, t0, budget)
            if h is not None and c < best_c:
                best_h = h
                best_c = c

    if best_h is None:
        # fallback
        N = 120
        x = np.linspace(-1.0, 1.0, N)
        best_h = np.exp(x)
        best_h /= best_h.sum()

    return np.asarray(best_h, dtype=float)

