def _slsqp(h0, N, maxiter, ftol, t0, budget):
    """Run the SLSQP formulation from p0156 starting at h0 (length N)."""
    best_h = np.asarray(h0, dtype=float).copy()
    best_c = _C(best_h)

    pairs = [[] for _ in range(2 * N - 1)]
    for i in range(N):
        for j in range(N):
            pairs[i + j].append((i, j))

