    def obj_grad(v):
        g = np.zeros(N + 1)
        g[N] = 1.0
        return g

    def conv_constraint(v):
        h = v[:N]
        z = v[N]
        return z - np.convolve(h, h)

    def conv_jac(v):
        h = v[:N]
        J = np.zeros((2 * N - 1, N + 1))
        for k in range(2 * N - 1):
            for (i, j) in pairs[k]:
                if i == j:
                    J[k, i] += -2.0 * h[i]
                else:
                    J[k, i] += -h[j]
                    J[k, j] += -h[i]
            J[k, N] = 1.0
        return J

