        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.sum() > 0:
            xs_old = np.linspace(0.0, 1.0, s.size)
            xs_new = np.linspace(0.0, 1.0, N)
            h_init = np.interp(xs_new, xs_old, s)
        else:
            h_init = None
    else:
        h_init = None

    if h_init is None:
        # p0156's best exponential ramp
        x = np.linspace(-1.0, 1.0, N)
        best_c = np.inf
        h_init = None
        for a in [0.5, 1.0, 1.5, 2.0, 3.0, 4.0, 6.0]:
            h = np.exp(a * x)
            h /= h.sum()
            c = _C(h)
            if c < best_c:
                best_c = c
                h_init = h.copy()

    h_init = np.clip(h_init, 0.0, None)
    if h_init.sum() <= 0:
        h_init = np.ones(N)
    h_init = h_init / h_init.sum()

    best_h, best_c = _slsqp(h_init, N, maxiter=2000, ftol=1e-14,
                            t0=t0, budget=budget_seconds)

    # Second SLSQP from a perturbed point, if time remains.
    if time.process_time() - t0 < budget_seconds * 0.7:
        rng = np.random.default_rng(12345)
        h_pert = best_h * np.exp(0.01 * rng.standard_normal(N))
        h_pert = np.clip(h_pert, 0.0, None)
        if h_pert.sum() > 0:
            h_pert /= h_pert.sum()
            h2, c2 = _slsqp(h_pert, N, maxiter=2000, ftol=1e-14,
                            t0=t0, budget=budget_seconds)
            if c2 < best_c:
                best_h, best_c = h2, c2

    # Compare with start.
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and s.sum() > 0 and _C(s) < best_c:
            return s

    return np.asarray(best_h, dtype=float)

import numpy as np
import time


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds * 0.80

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(50)
    else:
        best = np.ones(50)

    # Normalize so sum = 1 (C is scale-invariant, helps stability)
    best = best / best.sum()
    best_c = C_of(best)
    rng = np.random.default_rng(2024)

    def refine(h, factor):
        n = len(h)
        if n * factor > 30000:
            return h
        x_old = (np.arange(n) + 0.5) / n
        newn = n * factor
        x_new = (np.arange(newn) + 0.5) / newn
        return np.interp(x_new, x_old, h)

    # Try refining the start on multiple scales
    for f in [2, 4, 8, 16]:
        if time.process_time() - t0 > deadline:
            break
        h2 = refine(best, f)
        if len(h2) != len(best):
            c2 = C_of(h2)
            if c2 < best_c:
                best, best_c = h2, c2

    h = best.copy()
    cur_c = best_c
    n = len(h)

    # Coordinate descent: sweep all indices with multiplicative updates,
    # focusing effort on the region near the max of the convolution.
    step_sizes = [0.3, 0.1, 0.03, 0.01, 0.003, 0.001, 0.0003]

    while time.process_time() - t0 < deadline:
        improved = False
        # compute conv once to find where the max is on the grid
        conv = np.convolve(h, h)
        peak = int(np.argmax(conv))
        # indices of h that contribute most to conv[peak]: i and peak-i
        # focus on indices whose product h[i]*h[peak-i] is large
        contrib = np.zeros(n)
        for i in range(n):
            j = peak - i
            if 0 <= j < n:
                contrib[i] = h[i] * h[j]
        # top contributors
        order = np.argsort(-contrib)
        # We'll sweep the top contributors first, then the rest
        idx_order = np.concatenate([order[:min(n, 400)], order])
        # dedupe preserving order
        seen = np.zeros(n, dtype=bool)
        uniq = []
        for i in idx_order:
            if not seen[i]:
                seen[i] = True
                uniq.append(i)
        idx_order = np.array(uniq)

        for eps in step_sizes:
            if time.process_time() - t0 > deadline:
                break
            for i in idx_order:
                if time.process_time() - t0 > deadline:
                    break
                for sign in (1.0, -1.0):
                    h2 = h.copy()
                    h2[i] *= (1.0 + sign * eps)
                    if h2[i] < 0:
                        continue
                    s = h2.sum()
                    if s <= 0:
                        continue
                    h2 /= s
                    c2 = C_of(h2)
                    if c2 < cur_c - 1e-15:
                        h, cur_c = h2, c2
                        improved = True
                        break
        if not improved:
            # random block perturbation to escape
            bl = max(1, n // 8)
            i0 = rng.integers(0, n - bl + 1)
            h2 = h.copy()
            h2[i0:i0 + bl] *= np.exp(0.05 * rng.standard_normal(bl))
            s = h2.sum()
            if s > 0:
                h2 /= s
                c2 = C_of(h2)
                if c2 < cur_c:
                    h, cur_c = h2, c2
                else:
                    # small random kick
                    h2 = h * np.exp(0.01 * rng.standard_normal(n))
                    h2 /= h2.sum()
                    c2 = C_of(h2)
                    if c2 < cur_c:
                        h, cur_c = h2, c2
            else:
                break
        # occasionally try refining
        if time.process_time() - t0 < deadline * 0.5 and n < 30000:
            h2 = refine(h, 2)
            if len(h2) != n:
                c2 = C_of(h2)
                if c2 < cur_c:
                    h, cur_c, n = h2, c2, len(h2)

    if cur_c < best_c:
        best, best_c = h, cur_c

    return best

