    x_old = np.linspace(0.0, 1.0, len(h))
    x_new = np.linspace(0.0, 1.0, N2)
    h2 = np.interp(x_new, x_old, h)
    h2 = np.clip(h2, 0.0, None)
    if h2.sum() <= 0:
        return None
    return h2 / h2.sum()


