    seeds = []
    for a in [-3.0, -1.5, 0.0, 1.5, 3.0]:
        h = np.exp(a * x)
        h /= h.sum()
        seeds.append(h)
    h = np.clip(1.0 + np.cos(np.pi * x), 0.0, None)
    h /= h.sum()
    seeds.append(h)
    return seeds


