        if best_h is None:
            break
        h_up = _upsample(best_h, N2)
        if h_up is None:
            continue
        h, c = _slsqp_polish(h_up, iters)
        if h is not None and c < best_c:
            best_h, best_c = h, c

    # Final refinement at the same N as best, a couple more passes
    while time.process_time() - t0 < budget and best_h is not None:
        h, c = _slsqp_polish(best_h, 500)
        if h is not None and c < best_c - 1e-12:
            best_h, best_c = h, c
        else:
            break

    if best_h is None:
        N = 80
        x = np.linspace(-1.0, 1.0, N)
        best_h = np.exp(x)
        best_h /= best_h.sum()

    return np.asarray(best_h, dtype=float)

