        v = res.x
    except Exception:
        return h0, c0

    h = np.clip(v[:N], 0.0, None)
    if h.sum() <= 0:
        return h0, c0
    h = h / h.sum()
    c = _C(h)
    if c < c0:
        return h, c
    return h0, c0


def _perturb(h, rng, block=True):
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    if block:
        i = 0
        while i < N:
            b = int(rng.integers(4, 9))
            b = min(b, N - i)
            factor = rng.lognormal(0.0, 0.1)
            h[i:i + b] *= factor
            i += b
    else:
        h *= rng.lognormal(0.0, 0.1, N)
    h = np.clip(h, 0.0, None)
    s = h.sum()
    if s <= 0:
        return None
    return h / s


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.85
    rng = np.random.default_rng(12345)

    best_h = None
    best_c = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            cs = _C(s)
            if np.isfinite(cs):
                best_h = s.copy()
                best_c = cs

    if best_h is None:
        N = 80
        x = np.linspace(-1.0, 1.0, N)
        best_h = np.exp(x)
        best_h /= best_h.sum()
        best_c = _C(best_h)

    # Restarts at N=80 and N=120 from perturbed copies of the start.
    for N_target, n_restarts in [(80, 40), (120, 20)]:
        if time.process_time() - t0 > budget:
            break
        # Build base at this N by resampling best_h
        if len(best_h) != N_target:
            x_old = np.linspace(0.0, 1.0, len(best_h))
            x_new = np.linspace(0.0, 1.0, N_target)
            base = np.interp(x_new, x_old, best_h)
        else:
            base = best_h.copy()
        base = np.clip(base, 0.0, None)
        if base.sum() <= 0:
            base = np.ones(N_target)
        base /= base.sum()

        for r in range(n_restarts):
            if time.process_time() - t0 > budget:
                break
            block = (r % 2 == 0)
            h_p = _perturb(base, rng, block=block)
            if h_p is None:
                continue
            h, c = _slsqp_polish(h_p, N_target, 300, t0, budget)
            if h is not None and c < best_c:
                best_h = h
                best_c = c

    return np.asarray(best_h, dtype=float)

