    x_new = np.linspace(0.0, 1.0, N)
    hu = np.interp(x_new, x_old, h)
    hu = np.clip(hu, 0.0, None)
    if hu.sum() <= 0:
        hu = np.ones(N)
    return hu


def _slsqp(h0, N, maxiter, ftol=1e-13):
    h0 = np.clip(np.asarray(h0, dtype=float), 0.0, None)
    if h0.sum() <= 0:
        return None, np.inf
    h0 = h0 / h0.sum()
    c0 = C_of(h0)

    # Precompute convolution index pairs (vectorized via diagonal offsets)
    idx = np.arange(N)

    def conv_constraint(v):
        return v[N] - np.convolve(v[:N], v[:N])

    def conv_jac(v):
        h = v[:N]
        J = np.zeros((2 * N - 1, N + 1))
        # For each k = i+j: d/d h_i (sum_{i+j=k} h_i h_j) = sum over pairs
        # Build via convolution of indicator: derivative w.r.t i is sum_j h_j over j=k-i, doubled on diagonal
        for k in range(2 * N - 1):
            i_lo = max(0, k - N + 1)
            i_hi = min(N - 1, k)
            for i in range(i_lo, i_hi + 1):
                j = k - i
                if i == j:
                    J[k, i] += -2.0 * h[i]
                elif i < j:
                    J[k, i] += -h[j]
                    J[k, j] += -h[i]
            J[k, N] = 1.0
        return J

    cons = [
        {'type': 'eq', 'fun': lambda v: np.sum(v[:N]) - 1.0,
         'jac': lambda v: np.concatenate([np.ones(N), [0.0]])},
        {'type': 'ineq', 'fun': conv_constraint, 'jac': conv_jac},
    ]
    bounds = [(0.0, None)] * N + [(0.0, None)]
    v0 = np.concatenate([h0, [c0]])

    try:
        res = minimize(lambda v: v[N],
                       v0, jac=lambda v: np.concatenate([np.zeros(N), [1.0]]),
                       method='SLSQP', bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        v = res.x
    except Exception:
        return h0, c0

    h = np.clip(v[:N], 0.0, None)
    if h.sum() <= 0:
        return h0, c0
    h = h / h.sum()
    c = C_of(h)
    return (h, c) if c < c0 else (h0, c0)


