    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _conv_and_grad(h, w):
    """Return conv(h,h) and gradient of <w, conv(h,h)> w.r.t. h."""
    q = np.convolve(h, h)
    N = len(h)
    # d/dh_i sum_k w_k q_k = 2 * sum_j w_{i+j} h_j
    gh = 2.0 * np.convolve(w, h)[N - 1:2 * N - 1]
    return q, gh


def _lse_max(q, beta):
    m = np.max(q)
    return m + np.log(np.sum(np.exp(beta * (q - m)))) / beta


def _lse_w(q, beta):
    m = np.max(q)
    w = np.exp(beta * (q - m))
    return w / w.sum()


def _softmax(z):
    z = z - np.max(z)
    e = np.exp(z)
    return e / e.sum()


def _lbfgs_softmax(z0, betas, deadline, maxiter=400):
    """Minimize LSE_beta(conv(h,h)) - 2 log(sum h), h=softmax(z), for each beta."""
    from scipy.optimize import minimize
    z = z0.copy()

    def make_fun(beta):
        def f(z):
            h = _softmax(z)
            q = np.convolve(h, h)
            val = _lse_max(q, beta)
            w = _lse_w(q, beta)
            N = len(h)
            gh = 2.0 * np.convolve(w, h)[N - 1:2 * N - 1]
            # softmax jacobian: dz_i = h_i*(gh_i - <h,gh>)
            gz = h * (gh - np.dot(h, gh))
            return val, gz
        return f

    for beta in betas:
        if time.process_time() > deadline:
            break
        f = make_fun(beta)
        try:
            res = minimize(f, z, jac=True, method='L-BFGS-B',
                           options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-11})
            z = res.x
        except Exception:
            pass
    return _softmax(z)


def _slsqp_polish(h0, maxiter, deadline):
    """Directly minimize max(conv(h,h)) s.t. sum h=1, h>=0, conv(h,h)<=c."""
    from scipy.optimize import minimize
    h0 = np.clip(np.asarray(h0, dtype=float), 0.0, None)
    if h0.sum() <= 0:
        return h0, np.inf
    h0 = h0 / h0.sum()
    N = len(h0)
    c0 = _C(h0)

    # Precompute pair index lists for the Jacobian of conv
    pairs = [[] for _ in range(2 * N - 1)]
    for i in range(N):
        for j in range(N):
            pairs[i + j].append((i, j))

    def obj(v):
        return v[N]

    def obj_grad(v):
        g = np.zeros(N + 1)
        g[N] = 1.0
        return g

    def conv_constraint(v):
        return v[N] - np.convolve(v[:N], v[:N])

    def conv_jac(v):
        h = v[:N]
        J = np.zeros((2 * N - 1, N + 1))
        for k in range(2 * N - 1):
            for (i, j) in pairs[k]:
                if i == j:
                    J[k, i] += -2.0 * h[i]
                else:
                    J[k, i] += -h[j]
                    J[k, j] += -h[i]
            J[k, N] = 1.0
        return J

    cons = [
        {'type': 'eq', 'fun': lambda v: np.sum(v[:N]) - 1.0,
         'jac': lambda v: np.concatenate([np.ones(N), [0.0]])},
        {'type': 'ineq', 'fun': conv_constraint, 'jac': conv_jac},
    ]
    bounds = [(0.0, None)] * N + [(0.0, None)]
    v0 = np.concatenate([h0, [c0]])

    if time.process_time() > deadline:
        return h0, c0
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-13})
        v = res.x
    except Exception:
        return h0, c0

    h = np.clip(v[:N], 0.0, None)
    if h.sum() <= 0:
        return h0, c0
    h = h / h.sum()
    c = _C(h)
    return (h, c) if c < c0 else (h0, c0)


