    xo = np.linspace(0.0, 1.0, len(h))
    xn = np.linspace(0.0, 1.0, N2)
    return np.clip(np.interp(xn, xo, h), 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_c = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            cs = _C(s)
            if np.isfinite(cs):
                best_h = s.copy()
                best_c = cs

    if best_h is None:
        N = 200
        x = np.linspace(-1.0, 1.0, N)
        best_h = np.exp(0.5 * x)
        best_c = _C(best_h)

    # Stage A: LSE-annealed L-BFGS polish at the start's resolution
    N0 = len(best_h)
    betas = [1e2, 3e2, 1e3, 3e3, 1e4, 3e4, 1e5, 3e5]
    if time.process_time() < deadline:
        h_init = best_h / best_h.sum()
        z0 = np.log(np.clip(h_init, 1e-12, None))
        z0 -= z0.mean()
        h_sm = _lbfgs_softmax(z0, betas, deadline)
        c_sm = _C(h_sm)
        if c_sm < best_c:
            best_h, best_c = h_sm, c_sm
        print("LSE polish N=%d c=%.9f" % (N0, c_sm))

    # Stage B: SLSQP direct polish at same N
    if time.process_time() < deadline:
        h, c = _slsqp_polish(best_h, 800, deadline)
        if c < best_c:
            best_h, best_c = h, c
        print("SLSQP polish N=%d c=%.9f" % (len(best_h), c))

    # Stage C: upsample to higher N and re-polish with SLSQP (finite N helps)
    for N2 in (2000, 4000):
        if time.process_time() > deadline:
            break
        h_up = _upsample(best_h, N2)
        h_up = h_up / h_up.sum()
        c_up = _C(h_up)
        # only trust the upsample if it's already competitive
        if c_up < best_c * 1.02:
