            if c < best_c:
                best_h, best_c = h, c
            print("SLSQP upsample N=%d c=%.9f" % (N2, c))

    # Stage D: final LSE polish at high N if budget remains
    if time.process_time() < deadline:
        h_init = best_h / best_h.sum()
        z0 = np.log(np.clip(h_init, 1e-12, None))
        z0 -= z0.mean()
        h_sm = _lbfgs_softmax(z0, [1e4, 3e4, 1e5], deadline, maxiter=200)
        c_sm = _C(h_sm)
        if c_sm < best_c:
            best_h, best_c = h_sm, c_sm
        print("final LSE N=%d c=%.9f" % (len(best_h), c_sm))

    print("best C =", best_c)
    return np.asarray(best_h, dtype=float)

