def _conv_grad(h, k):
    """Gradient of (h*h)[k] w.r.t. h."""
    N = len(h)
    g = np.zeros(N)
    # (h*h)[k] = sum_{i+j=k} h[i]h[j]
    lo = max(0, k - (N - 1))
    hi = min(N - 1, k)
    for i in range(lo, hi + 1):
