            g[i] += 2.0 * h[i]
        else:
            g[i] += h[j]
    return g


def _polish(h0, N, maxiter, t0, budget, ftol=1e-14):
    """Minimise C via SLSQP with analytic Jacobian (banded conv)."""
    h0 = np.asarray(h0, dtype=float)
    h0 = np.clip(h0, 0.0, None)
    if h0.sum() <= 0:
        return None, np.inf
    h0 = h0 / h0.sum()
    c0 = _C(h0)

    def obj(v):
        return v[N]

    def obj_grad(v):
        g = np.zeros(N + 1)
        g[N] = 1.0
        return g

    def conv_constraint(v):
        return v[N] - np.convolve(v[:N], v[:N])

    def conv_jac(v):
        h = v[:N]
        J = np.zeros((2 * N - 1, N + 1))
        for k in range(2 * N - 1):
            J[k, :N] = -_conv_grad(h, k)
            J[k, N] = 1.0
        return J

    cons = [
        {'type': 'eq', 'fun': lambda v: np.sum(v[:N]) - 1.0,
         'jac': lambda v: np.concatenate([np.ones(N), [0.0]])},
        {'type': 'ineq', 'fun': conv_constraint, 'jac': conv_jac},
    ]
    bounds = [(0.0, None)] * N + [(0.0, None)]
    v0 = np.concatenate([h0, [c0]])

    if time.process_time() - t0 > budget:
        return h0, c0
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        v = res.x
    except Exception:
        return h0, c0

    h = np.clip(v[:N], 0.0, None)
    if h.sum() <= 0:
        return h0, c0
    h = h / h.sum()
    c = _C(h)
    if c < c0:
        return h, c
    return h0, c0


def _upsample(h, N):
    x_old = np.linspace(0.0, 1.0, len(h))
    x_new = np.linspace(0.0, 1.0, N)
    hu = np.interp(x_new, x_old, h)
    hu = np.clip(hu, 0.0, None)
    if hu.sum() <= 0:
        hu = np.ones(N)
    return hu / hu.sum()


def _downsample(h, N):
    """Average-pool h to N steps (N < len(h))."""
    L = len(h)
    if N >= L:
        return _upsample(h, N)
    idx = np.linspace(0, L, N + 1).astype(int)
    out = np.array([h[idx[i]:idx[i + 1]].mean() for i in range(N)])
    out = np.clip(out, 0.0, None)
    if out.sum() <= 0:
        out = np.ones(N)
    return out / out.sum()


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.85

    best_h = None
    best_c = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            cs = _C(s)
            if np.isfinite(cs):
                best_h = s.copy()
                best_c = cs

    if best_h is None:
        N = 120
        x = np.linspace(-1.0, 1.0, N)
        best_h = np.exp(x)
        best_h /= best_h.sum()
        best_c = _C(best_h)

    base_N = len(best_h)

    # 1) Polish the start at its own resolution.
    if time.process_time() - t0 < budget:
        h, c = _polish(best_h, base_N, 1000, t0, budget)
        if h is not None and c < best_c:
            best_h, best_c = h, c

    # 2) Try upsampled resolutions (finer discretisation of same profile).
    for N in [base_N + 40, base_N + 80, 2 * base_N, 320]:
        if time.process_time() - t0 > budget:
            break
        if N > 30000:
            continue
        h_up = _upsample(best_h, N)
        h, c = _polish(h_up, N, 1000, t0, budget)
        if h is not None and c < best_c:
            best_h, best_c = h, c

    # 3) Try zeroing small heights at several thresholds, then re-polish.
    for t in [0.005, 0.01, 0.02, 0.04, 0.07]:
        if time.process_time() - t0 > budget:
            break
        h = best_h.copy()
        mx = h.max()
        if mx <= 0:
            continue
        h[h < t * mx] = 0.0
        if h.sum() <= 0:
            continue
        h = h / h.sum()
        h2, c2 = _polish(h, len(h), 800, t0, budget)
        if h2 is not None and c2 < best_c:
            best_h, best_c = h2, c2

    # 4) Try downsampling (coarser representation may smooth out noise).
    if base_N > 60:
        for N in [base_N // 2, base_N * 2 // 3]:
            if time.process_time() - t0 > budget:
                break
            h_dn = _downsample(best_h, N)
            h, c = _polish(h_dn, N, 800, t0, budget)
            if h is not None and c < best_c:
                best_h, best_c = h, c

    return np.asarray(best_h, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _slsqp_polish(h0, N, maxiter, t0, budget, ftol=1e-13):
    h0 = np.asarray(h0, dtype=float)
    h0 = np.clip(h0, 0.0, None)
    if h0.sum() <= 0:
        return None, np.inf
    h0 = h0 / h0.sum()
    c0 = _C(h0)

    def obj(v):
        return v[N]

    def obj_grad(v):
        g = np.zeros(N + 1)
        g[N] = 1.0
        return g

    def conv_constraint(v):
        return v[N] - np.convolve(v[:N], v[:N])

    def conv_jac(v):
        h = v[:N]
        J = np.zeros((2 * N - 1, N + 1))
        for i in range(N):
            e = np.zeros(N)
            e[i] = 1.0
            J[:, i] = -(np.convolve(e, h) + np.convolve(h, e))
        J[:, N] = 1.0
        return J

    cons = [
        {'type': 'eq', 'fun': lambda v: np.sum(v[:N]) - 1.0,
         'jac': lambda v: np.concatenate([np.ones(N), [0.0]])},
        {'type': 'ineq', 'fun': conv_constraint, 'jac': conv_jac},
    ]
    bounds = [(0.0, None)] * N + [(0.0, None)]
    v0 = np.concatenate([h0, [c0]])

    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        v = res.x
    except Exception:
        return h0, c0

    h = np.clip(v[:N], 0.0, None)
    if h.sum() <= 0:
        return h0, c0
    h = h / h.sum()
    c = _C(h)
    if c < c0:
        return h, c
    return h0, c0


def _upsample(h, N):
    x_old = np.linspace(0.0, 1.0, len(h))
    x_new = np.linspace(0.0, 1.0, N)
    hu = np.interp(x_new, x_old, h)
    hu = np.clip(hu, 0.0, None)
    if hu.sum() <= 0:
        hu = np.ones(N)
    return hu / hu.sum()


def _adaptive_upsample(h, N_target):
    """Non-uniform refinement: sample h at x positions where either the
    second difference of h is large, or the local convolution contribution
    is near the maximum. Always include uniform baseline points."""
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n < 3 or N_target <= n:
        return _upsample(h, max(N_target, 1))

    # second difference magnitude per interior point
    d2 = np.abs(h[2:] - 2.0 * h[1:-1] + h[:-2])
    # convolution contribution per index (approx): h_i * (h*h)_i-ish
    conv = np.convolve(h, h)
    cmax = conv.max() if conv.size else 0.0
    # map conv knots back to h-index regions: knot k ~ index k/2
    near_max = np.zeros(n)
    if cmax > 0:
        thresh = 0.995 * cmax
        for k in range(conv.size):
            if conv[k] >= thresh:
                i = k // 2
                if 0 <= i < n:
                    near_max[i] = 1.0

    # score each interval between h[i] and h[i+1]
    score = np.zeros(n - 1)
    if d2.size:
        d2p = np.concatenate([[d2[0]], d2, [d2[-1]]])
        d2p = np.clip(d2p, 0.0, None)
        if d2p.max() > 0:
            d2n = d2p / d2p.max()
        else:
            d2n = d2p
    else:
        d2n = np.zeros(n)
    for i in range(n - 1):
        s = 0.5 * (d2n[i] + d2n[i + 1])
        if near_max[i] > 0 or near_max[i + 1] > 0:
            s += 1.0
        score[i] = s

    if score.max() <= 0:
        return _upsample(h, N_target)

    # top 20% intervals get extra points
    order = np.argsort(-score)
    n_top = max(1, int(0.2 * len(order)))
    top_set = set(order[:n_top].tolist())

    # build x positions: baseline uniform + extra in top intervals
    base = N_target // 2
    xs = list(np.linspace(0.0, 1.0, base))
    extra = N_target - base
    if extra > 0 and top_set:
        per = max(1, extra // len(top_set))
        for i in top_set:
            x0 = i / (n - 1)
            x1 = (i + 1) / (n - 1)
            for j in range(1, per + 1):
                xs.append(x0 + (x1 - x0) * j / (per + 1))
    xs = np.array(sorted(set(xs)))
    if len(xs) > N_target:
        idx = np.linspace(0, len(xs) - 1, N_target).astype(int)
        xs = xs[idx]
    x_old = np.linspace(0.0, 1.0, n)
    hu = np.interp(xs, x_old, h)
    hu = np.clip(hu, 0.0, None)
    if hu.sum() <= 0:
        hu = np.ones(len(hu))
    return hu / hu.sum()


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.88

    best_h = None
    best_c = np.inf

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            cs = _C(s)
            if np.isfinite(cs):
                best_h = s.copy()
                best_c = cs

    if best_h is None:
        N = 120
        x = np.linspace(-1.0, 1.0, N)
        best_h = np.exp(x)
        best_h /= best_h.sum()
        best_c = _C(best_h)

    for N in [160, 200, 240, 320, 400, 600, 800, 1200, 1600, 2000]:
        if time.process_time() - t0 > budget:
            break
        N = min(N, 2000)
        h_up = _adaptive_upsample(best_h, N)
        h, c = _slsqp_polish(h_up, len(h_up), 2000, t0, budget, ftol=1e-14)
        if h is not None and c < best_c - 1e-12:
            best_h = h
            best_c = c
            print("N=%d c=%.9f t=%.1f" % (len(h), c, time.process_time() - t0))

    print("final C=%.9f N=%d" % (best_c, len(best_h)))
    return np.asarray(best_h, dtype=float)

import numpy as np
import time


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    """Refine the best-known profile using a smooth-parametric family plus a fine
    grid search over the family parameters. The optimal f is known to be smooth,
    so searching a low-dimensional parametric family (e.g. a cosine bump raised to
    a power, or a Gaussian-like family) is a cheaper and more reliable route to a
    very low C than direct high-dimensional optimisation on N=1000 heights.

    We try several families, each parameterised by a few numbers, and pick the
    best. We keep the start as a fallback and also try fine grid search near the
    start profile via multiplicative block perturbations followed by local search
    on the family parameters.
    """
    t0 = time.process_time()
    deadline = budget_seconds * 0.85

    best_h = None
    best_c = np.inf
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            cs = _C(s)
            if np.isfinite(cs):
                best_h = s.copy()
                best_c = cs

    N = 4000  # evaluation resolution for candidate shapes
    x = -0.25 + (np.arange(N) + 0.5) / (2.0 * N)  # centres in [-1/4,1/4]

    def eval_shape(h):
        s = h.sum()
        if s <= 0:
            return np.inf
        return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)

    # Family 1: exp(lambda * x) with lambda in [0, 12]
    lam_grid = np.linspace(0.0, 12.0, 601)
    for lam in lam_grid:
        if time.process_time() - t0 > deadline:
            break
        h = np.exp(lam * x)
        c = eval_shape(h)
        if c < best_c:
            best_c = c
            best_h = h.copy()

    # Family 2: cos bumps: cos(pi * x / w)^p on |x| < w/2, 0 outside.
    # Parameterised by width w in (0, 0.5] and power p.
    for w in np.linspace(0.30, 0.50, 21):
        if time.process_time() - t0 > deadline:
            break
        mask = np.abs(x) < (w * 0.5)
        if mask.sum() < 4:
            continue
        xin = x[mask]
        for p in np.linspace(0.2, 6.0, 30):
            if time.process_time() - t0 > deadline:
                break
            h = np.zeros(N)
            h[mask] = np.cos(np.pi * xin / w) ** p
            c = eval_shape(h)
            if c < best_c:
                best_c = c
                best_h = h.copy()

    # Family 3: raised cosine bump (smooth compact support): h = (1 - (2x/w)^2)^p
    for w in np.linspace(0.30, 0.50, 21):
        if time.process_time() - t0 > deadline:
            break
        mask = np.abs(x) < (w * 0.5)
        if mask.sum() < 4:
            continue
        u = (2.0 * x[mask] / w) ** 2
        u = np.clip(u, 0.0, 1.0)
        base = 1.0 - u
        for p in np.linspace(0.2, 8.0, 40):
            if time.process_time() - t0 > deadline:
                break
            h = np.zeros(N)
            h[mask] = base ** p
            c = eval_shape(h)
            if c < best_c:
                best_c = c
                best_h = h.copy()

    # Family 4: Gaussian-like bump: exp(-(x/sigma)^2) with sigma in (0, 0.5]
    for sigma in np.linspace(0.05, 0.30, 60):
        if time.process_time() - t0 > deadline:
            break
        h = np.exp(-(x / sigma) ** 2)
        c = eval_shape(h)
        if c < best_c:
            best_c = c
            best_h = h.copy()

    # Family 5: generalized Gaussian exp(-|x/sigma|^q)
    for sigma in np.linspace(0.05, 0.30, 26):
        if time.process_time() - t0 > deadline:
            break
        for q in np.linspace(0.5, 4.0, 20):
            if time.process_time() - t0 > deadline:
                break
            h = np.exp(-(np.abs(x) / sigma) ** q)
            c = eval_shape(h)
            if c < best_c:
                best_c = c
                best_h = h.copy()

    # Family 6: piecewise power-law bump: (1 - |2x/w|)^p inside, 0 outside
    for w in np.linspace(0.30, 0.50, 21):
        if time.process_time() - t0 > deadline:
            break
        mask = np.abs(x) < (w * 0.5)
        if mask.sum() < 4:
            continue
        base = 1.0 - np.abs(2.0 * x[mask] / w)
        base = np.clip(base, 0.0, None)
        for p in np.linspace(0.2, 6.0, 30):
            if time.process_time() - t0 > deadline:
                break
            h = np.zeros(N)
            h[mask] = base ** p
            c = eval_shape(h)
            if c < best_c:
                best_c = c
                best_h = h.copy()

    # Final local refinement: coordinate-wise multiplicative rescan around the best
    # family member, evaluated on a fine grid.
    if best_h is not None and time.process_time() - t0 < deadline:
        h = best_h.copy()
        s = h.sum()
        if s > 0:
            h = h / s
        # Try to refine using a smooth bump of the family that produced the best
        # result: we don't know which, so do a small 2-D refinement over
        # (width, power) of the raised-cosine family around the current best.
        # This is quick and can improve C slightly.
        best_h_ref = h.copy()
        best_c_ref = _C(h)
        for w in np.linspace(0.32, 0.48, 17):
            if time.process_time() - t0 > deadline:
                break
            mask = np.abs(x) < (w * 0.5)
            if mask.sum() < 4:
                continue
            u = (2.0 * x[mask] / w) ** 2
            u = np.clip(u, 0.0, 1.0)
            base = 1.0 - u
            for p in np.linspace(0.5, 5.0, 46):
                if time.process_time() - t0 > deadline:
                    break
                hh = np.zeros(N)
                hh[mask] = base ** p
                c = eval_shape(hh)
                if c < best_c_ref:
                    best_c_ref = c
                    best_h_ref = hh.copy()
        if best_c_ref < best_c:
            best_c = best_c_ref
            best_h = best_h_ref

    if best_h is None:
        best_h = np.ones(N)
    best_h = np.clip(best_h, 0.0, None)
    if best_h.sum() <= 0:
        best_h = np.ones(N)

    print("best C =", float(_C(best_h)), "N =", len(best_h))
    return best_h
